update stock_out_detail
warehouse_code = #{warehouseCode}, workshop_code = #{workshopCode}, location_code = #{locationCode}, prod_order_no = #{prodOrderNo}, order_no = #{orderNo}, line_no = #{lineNo}, mat_code = #{matCode}, mat_name = #{matName}, fd_code = #{fdCode}, fig_num = #{figNum}, mat_group = #{matGroup}, mat_class = #{matClass}, batch = #{batch}, quantity = #{quantity}, received_quantity = #{receivedQuantity}, unit_code = #{unitCode}, supplier_code = #{supplierCode}, supplier_name = #{supplierName}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
